mapper.select:
SELECT id, from_user_id, to_user_id, content, is_read, created_at
FROM message
WHERE id = #{id}

SELECT t.id, t.from_user_id, t.to_user_id, t.content, t.is_read, t.created_at
FROM (
    (SELECT id, from_user_id, to_user_id, content, is_read, created_at
     FROM message
     WHERE from_user_id = #{userId}
       AND to_user_id = #{friendId}

       AND id < #{beforeId}

     ORDER BY id DESC
     LIMIT #{limit})
    UNION ALL
    (SELECT id, from_user_id, to_user_id, content, is_read, created_at
     FROM message
     WHERE from_user_id = #{friendId}
       AND to_user_id = #{userId}

       AND id < #{beforeId}

     ORDER BY id DESC
     LIMIT #{limit})
) t
ORDER BY t.id DESC
LIMIT #{limit}

